import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import {
  useParams,
  NavLink,
  Outlet,
  useLocation,
  useNavigate,
} from "react-router-dom";
import "./roiTabs.css";

export default function ProjectLeadROIEntry() {
  const { intakeNumber } = useParams();
  const location = useLocation();
  const navigate = useNavigate();

  const [rows, setRows] = useState([
    {
      Release: "",
      ROIMonth: "",
      ProjectName: "",
      AutomationLead: "",
      SavingsCategory: "",
      AutomationFmk: "",
      TotalTCsCount: "",
      ManualTCsPD: "",
      AutomatedTCCreatedPD: "",
      NumberofCycles: "",
      TotalManualPD: 0,
      TotalManualCost: 0,
      TotalAutomatedPD: 0,
      TotalAutomationCost: 0,
      Savings: 0,
    },
  ]);

  const [projectDetails, setProjectDetails] = useState(null);

  const handleChange = (index, field, value) => {
    setRows((prev) => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: value };
      return copy;
    });
  };

  const deleteRow = (index) => {
    setRows((prev) => {
      const copy = [...prev];
      copy.splice(index, 1);
      return copy;
    });
  };

  useEffect(() => {
    if (!intakeNumber) return;
    axios
      .get(`http://localhost:5000/api/projects/${intakeNumber}`)
      .then((res) => {
        setProjectDetails(res.data);
        const currentMonth = new Date().toLocaleString("default", {
          month: "long",
          year: "numeric",
        });
        setRows((prev) =>
          prev.map((row) => ({
            ...row,
            ProjectName: res.data?.intake_name || "",
            AutomationLead: res.data?.automation_qe_lead || "",
            Release: res.data?.release || row.Release,
            ROIMonth: currentMonth || row.ROIMonth,
          }))
        );
      })
      .catch((err) => {
        console.error("Error fetching project details", err);
      });
  }, [intakeNumber]);

  // default “summary” if the user lands at the parent
  useEffect(() => {
    const base = `/ROI/ProjectLeadROIEntry/${intakeNumber}`;
    const isOnBase =
      location.pathname === base || location.pathname === `${base}/`;
    if (intakeNumber && isOnBase) navigate("SummaryTab", { replace: true });
  }, [location.pathname, intakeNumber, navigate]);

  const mainSegment = useMemo(() => {
    const parts = location.pathname.split("/");
    const idx = parts.indexOf(intakeNumber);
    return idx !== -1 ? (parts[idx + 1] || "SummaryTab") : "SummaryTab";
  }, [location.pathname, intakeNumber]);

  
  
  
  const onSave = () => {
    console.log(`Save clicked for main tab: ${mainSegment}`);
  };

  return (
    <div className="p-4">
      <h2 className="text-xl font-semibold mb-4">
        Project Lead ROI Entry — Intake #{intakeNumber}
      </h2>

      {/* MAIN tabs */}
      <div className="roi-tabs">
        <NavLink className="roi-tab" to={`SummaryTab`}>Summary</NavLink>
        <NavLink className="roi-tab" to={`ProjectStatusTab`}>Project Status (Master intake)</NavLink>
        <NavLink className="roi-tab" to={`test-case-count`}>Test Case count (Master Dashboard)</NavLink>
        {/* CHANGED: go directly to Project Savings child */}
        <NavLink className="roi-tab" to={`savings/project`}>Savings</NavLink>
        <NavLink className="roi-tab" to={`monthly-breakup`}>Monthly Breakup</NavLink>
      </div>

      {/* Save button for each main tab */}
      <div style={{ display: "flex", justifyContent: "flex-end", margin: "10px 0" }}>
        <button className="btn-red" onClick={onSave}>&lt;Save&gt;</button>
      </div>

      {/* Outlet renders main-tab content (Summary / Project Status / Test Case Count / Savings / Monthly Breakup) */}
      <div className="roi-tab-panel">
        <Outlet context={{ intakeNumber, projectDetails, rows, setRows }} />
      </div>

      {/* Project details header (reduced inputs) */}
      <div className="space-y-4 mb-6 mt-6">
        <h3 className="text-lg font-semibold text-gray-700">Project Details</h3>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">Release:</label>
          <input
            type="text"
            value={rows[0]?.Release || ""}
            onChange={() => {}}
            disabled
            className="flex-1 border rounded-md px-2 py-1 bg-gray-100"
          />
        </div>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">ROI Month:</label>
          <input
            type="text"
            value={rows[0]?.ROIMonth || ""}
            onChange={(e) => handleChange(0, "ROIMonth", e.target.value)}
            className="flex-1 border rounded-md px-2 py-1"
          />
        </div>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">Project Name:</label>
          <input
            type="text"
            value={rows[0]?.ProjectName || ""}
            disabled
            className="flex-1 border rounded-md px-2 py-1 bg-gray-100"
          />
        </div>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">Automation Lead:</label>
          <input
            type="text"
            value={rows[0]?.AutomationLead || ""}
            disabled
            className="flex-1 border rounded-md px-2 py-1 bg-gray-100"
          />
        </div>
      </div>
    </div>
  );
}
